const int MAX_CAP = 1e6 + 1e5, MOD_CONST = 1e9 + 7;

LL base_num, mod_num;
int total_count;
LL final_ans;
int visited_array[MAX_CAP];
int val_array[MAX_CAP];

void modify_value(LL &x) { x = (x % MOD_CONST + MOD_CONST) % MOD_CONST; }

void perform_bfs(int x)
{
    ++total_count;
    int start_point = x;
    LL weight = 1;
    do {
        visited_array[x] = true;
        x = x * base_num % mod_num;
        weight = weight * base_num % mod_num;
    } while (x != start_point);
    modify_value(final_ans *= (weight == 1 ? mod_num : 1));
}

void main_solve()
{
    if (base_num == 0) {
        LL product = 1;
        LOOP_VAR(i, 1, mod_num - 1)
            product = product * mod_num % MOD_CONST;
        printf("%lld\n", product);
        return;
    }
    final_ans = 1;
    LOOP_VAR(i, 0, mod_num - 1)
        if (visited_array[i] == 0)
            perform_bfs(i);
    printf("%lld\n", final_ans);
}

int main()
{
    if (fopen("B.in", "r") != NULL) {
        freopen("B.in", "r", stdin);
